SELECT game_id AS "gameId", listener_id AS "listenerId", sequence_id AS "sequenceId", change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.listener_effect_sequences WHERE game_id = #{gameId}
AND listener_id = #{listenerId}
AND sequence_id = #{sequenceId}
ORDER BY listener_id, sequence_id

 SELECT
game_id AS "gameId",
listener_id AS "listenerId",
sequence_id AS "sequenceId",
change_revision AS "changeRevision",
updated_at AS "updatedAt"
 FROM public.listener_effect_sequences
 WHERE game_id = #{gameId}
